from pydantic import BaseModel, Field

class CalculoArgs(BaseModel):
    expresion: str = Field(description="Operacion matematica, ej: (1200 * 1.16) - 50")

def tool_calculo(expresion: str) -> float:
    # Evaluacion segura de operaciones aritmeticas
    return eval(expresion, {"__builtins__": None}, {})

